from pathlib import Path
import tempfile
import subprocess
import shutil
r=Path(tempfile.mkdtemp(prefix="leaf-toolring-"))
def put(p,s):
 f=r/p;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(s)
put('common/common_types.h','#pragma once\n#include <cstdint>\nusing u8=uint8_t;using u16=uint16_t;using u32=uint32_t;using u64=uint64_t;using s32=int32_t;\n')
put('common/logging/log.h','#pragma once\n#define LOG_INFO(...) (void)0\n')
put('core/hle/kernel/process.h','#pragma once\n#include <memory>\n#include <vector>\n#include "common/common_types.h"\nnamespace Kernel { struct CodeSet {struct Segment {u32 addr=0x100000,size=0x1000;};u64 program_id=0x0004000000198e00ULL;Segment segment;const Segment& CodeSegment() const{return segment;}};struct Process {std::shared_ptr<CodeSet> codeset=std::make_shared<CodeSet>();};}\n')
put('core/memory.h','#pragma once\n#include <vector>\n#include <cstring>\n#include <cassert>\n#include "core/hle/kernel/process.h"\nnamespace Memory {struct MemorySystem {std::vector<u8> data=std::vector<u8>(0x2000000);bool IsValidVirtualAddress(const Kernel::Process&,u32 a){return a>=0x100000 && a<data.size();}u8 Read8(const Kernel::Process&,u32 a){return data.at(a);}u16 Read16(const Kernel::Process&,u32 a){u16 v;memcpy(&v,&data.at(a),2);return v;}u32 Read32(const Kernel::Process&,u32 a){u32 v;memcpy(&v,&data.at(a),4);return v;}void Write16(const Kernel::Process&,u32 a,u16 v){memcpy(&data.at(a),&v,2);}void Write32(const Kernel::Process&,u32 a,u32 v){memcpy(&data.at(a),&v,4);}void ReadBlock(const Kernel::Process&,u32 a,void* p,size_t n){memcpy(p,&data.at(a),n);}};}\n')
put('core/arm/arm_interface.h','#pragma once\n#include <array>\n#include "common/common_types.h"\nstruct CPU {std::array<u32,16> regs{};u32 GetPC(){return regs[15];}u32 GetReg(int i){return regs[i];}void SetReg(int i,u32 v){regs[i]=v;}};\n')
put('core/hle/kernel/kernel.h','#pragma once\n#include "core/hle/kernel/process.h"\nstruct KernelMock {std::shared_ptr<Kernel::Process> p=std::make_shared<Kernel::Process>();auto GetCurrentProcess(){return p;}};\n')
put('core/core.h','#pragma once\n#include "core/memory.h"\n#include "core/arm/arm_interface.h"\n#include "core/hle/kernel/kernel.h"\nnamespace Core {struct System {Memory::MemorySystem memory;KernelMock kernel;CPU cpu;auto& Memory(){return memory;}auto& Kernel(){return kernel;}auto& GetRunningCore(){return cpu;}void InvalidateCacheRange(u32,size_t){}};}\n')

put("test.cpp",'#include <cassert>\n#include <iostream>\n#include <fstream>\n#include <iterator>\n#include "core/leaf_acnl/tool_ring.cpp"\nint main(){\n    Core::System system;\n    auto& p=*system.kernel.p;\n    auto& m=system.memory;\n    auto write=[&](u32 a,std::initializer_list<u32> words){for(auto w:words){m.Write32(p,a,w);a+=4;}};\n    write(0x100100,{0xe92d4070,0xe1a05001,0xe1a04002,0xe1a06000,0xeb000000,0xe5951000,0xe1a02000,0xe3a03000,0xe5a01000,0xe3a01000,0xe5c04004,0xe1a00006,0xe8bd4070,0xea000000});\n    write(0x100200,{0xe92d4070,0xe1a04000,0xe1a05001,0xe3a00004,0xe3a01000,0xeb000000,0xe3500000,0x0a000000,0xe5d01000,LeafACNL::Branch(0x100224,0x100100)});\n    write(0x100300,{0xe92d4070,0xe1a04000,0xed2d8b02,0xe5d001a9,0xe35000e0});\n    write(0x100400,{0xe59f0018,0xe5900100,0xe2800a06,0xe2800e01,0xeb000000,0xe1b00fa0});\n    m.Write32(p,0x100420,0x180000);\n    write(0x100500,{0xe3500016,0x359f1018,0x30800080,0x30810100});\n    m.Write32(p,0x100524,0x190000);\n    for(u32 i=0;i<22;++i){m.Write16(p,0x190000+i*12,100+i*4);m.Write16(p,0x190000+i*12+2,103+i*4);}\n    std::vector<u8> archive(120);\n    std::memcpy(archive.data(),"darc",4);\n    const u32 table=28,count=2,offset=80,size=40;\n    std::memcpy(archive.data()+16,&table,4);\n    std::memcpy(archive.data()+36,&count,4);\n    archive[31]=1;\n    std::memcpy(archive.data()+44,&offset,4);\n    std::memcpy(archive.data()+48,&size,4);\n    const std::u16string name=u"icn_319.bclim";\n    std::memcpy(archive.data()+52,name.c_str(),(name.size()+1)*2);\n    std::memcpy(archive.data()+80,"CLIM",4);\n    LeafACNL::SetToolIconArchive(archive);\n    assert(LeafACNL::ToolIcon(319).size()==40);\n    LeafACNL::SetToolIconArchive({1,2,3});\n    assert(LeafACNL::ToolIcon(319).size()==40);\n    assert(LeafACNL::Locate(system,p));\n    assert(m.Read32(p,0x100300)==LeafACNL::Branch(0x100300,0x100f40));\n    assert(m.Read32(p,0x100f58)==LeafACNL::Branch(0x100f58,0x100200,true));\n    assert(m.Read32(p,0x100f6c)==LeafACNL::Branch(0x100f6c,0x100304));\n    assert(!LeafACNL::HandleSvc(system,0xac));\n    system.cpu.regs[15]=0x100f48;\n    system.cpu.regs[0]=0x210000;\n    m.Write32(p,0x180100,0x200000);\n    m.data[0x2101a9]=6;\n    for(u32 i=0;i<16;++i)m.Write32(p,0x206010+i*4,0x7ffe);\n    m.Write32(p,0x206010,156);\n    m.Write16(p,0x200026,161);m.Write16(p,0x200028,9);\n    LeafACNL::state.changed=LeafACNL::Clock::now()-std::chrono::seconds(3);\n    assert(LeafACNL::HandleSvc(system,0xad));\n    auto tools=LeafACNL::Tools();\n    assert(tools.size()==2 && tools[0].slot==-1 && tools[1].slot==0);\n    assert(!LeafACNL::Select(16));\n    assert(LeafACNL::Select(0));\n    system.cpu.regs[0]=0x210000;\n    assert(LeafACNL::HandleSvc(system,0xad));\n    assert(system.cpu.regs[0]==0x100f70);\n    assert(m.Read32(p,0x100f70)==156);\n    system.cpu.regs[15]=0x100f60;\n    system.cpu.regs[0]=1;\n    assert(LeafACNL::HandleSvc(system,0xad));\n    assert(m.Read32(p,0x206010)==(161u|(9u<<16)));\n    m.Write32(p,0x206010,156);\n    m.data[0x206050]=1;\n    system.cpu.regs[15]=0x100f48;system.cpu.regs[0]=0x210000;\n    assert(LeafACNL::Select(0));\n    assert(LeafACNL::HandleSvc(system,0xad));\n    assert(system.cpu.regs[0]==0);\n    system.cpu.regs[0]=0x210000;\n    m.Write32(p,0x180100,0xffffffff);\n    assert(LeafACNL::HandleSvc(system,0xad));\n    assert(system.cpu.regs[0]==0);\n    LeafACNL::ResetToolRing();\n    assert(LeafACNL::Tools().empty());\n    assert(!LeafACNL::Select(0));\n    std::cout<<"ToolRing synthetic guest integration checks passed\\n";\n}\n')
root=Path(__file__).resolve().parents[1]
try:
 subprocess.run(["g++","-std=c++17","-Wall","-Wextra","-Werror","-I"+str(r),"-I"+str(root/"src"),str(r/"test.cpp"),"-o",str(r/"test")],check=True)
 subprocess.run([str(r/"test")],check=True)
finally:
 shutil.rmtree(r)
